import{_ as t,C as s,o as e,c as h,j as i,E as r,a as l,a2 as n}from"./chunks/framework.C21TwvGF.js";const x=JSON.parse(`{"title":"6-dars (Mentor). Photoshop interfeysi va vositalari (2-qism): Tanlash vositalari, qatlamlar va uskunalar","description":"","frontmatter":{"title":"6-dars (Mentor). Photoshop interfeysi va vositalari (2-qism): Tanlash vositalari, qatlamlar va uskunalar","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":2,"link":"/mentor/9-sinf-game/hafta-02/"},"g":6,"title":"Photoshop interfeysi va vositalari (2-qism): Tanlash vositalari, qatlamlar va uskunalar","lead":"Professional grafik dizayner hech qachon rasmni buzib o'chirmaydi. U niqoblar (maskalar) va qatlamlar orqali sehrli o'zgarishlar yaratadi!","slide":"/slaydlar/9-sinf-game/hafta-02/dars-3.html","test":"/slaydlar/9-sinf-game/hafta-02/dars-3-test.html","student_link":"/9-sinf-game/hafta-02/dars-3","tabs":[{"g":4,"link":"/mentor/9-sinf-game/hafta-02/dars-1","current":false},{"g":5,"link":"/mentor/9-sinf-game/hafta-02/dars-2","current":false},{"g":6,"link":"/mentor/9-sinf-game/hafta-02/dars-3","current":true}],"prev":{"g":5,"title":"Photoshop interfeysi va vositalari (1-qism): 2D grafika turlari va interfeys","link":"/mentor/9-sinf-game/hafta-02/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-02/dars-3.md","filePath":"mentor/9-sinf-game/hafta-02/dars-3.md"}`),d={name:"mentor/9-sinf-game/hafta-02/dars-3.md"},m={class:"blk"},u={id:"dars-rejasi",tabindex:"-1"},g={class:"blk"},q={id:"mentor-konspekti",tabindex:"-1"},k={class:"blk"},y={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},c={class:"blk"},b={id:"tezkor-nazorat-savollari",tabindex:"-1"},v={class:"blk"},f={id:"uyga-vazifa",tabindex:"-1"};function p(_,a,z,T,M,S){const o=s("Icon");return e(),h("div",null,[i("div",m,[i("h2",u,[r(o,{name:"file-text"}),a[0]||(a[0]=l(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=n("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga Adobe Photoshop dasturidagi tanlash vositalari (Marquee, Lasso, Magic Wand / Quick Selection), chizish va tahrirlash asboblari (Brush, Eraser, Pen, Shape, Gradient), qatlamlar (Layers) ierarxiyasi, destruktiv bo&#39;lmagan tahrirlash — qatlam maskalari (Layer Masks) hamda aralashtirish rejimlari (Blending Modes)dan foydalanib o&#39;yin assetlari tayyorlashni o&#39;rgatish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar murakkab shakldagi o&#39;yin obyektlarini fondan ajrata oladi; qatlamlar va maskalar bilan buzilmasdan (non-destructive) ishlay oladi; Blending Modes orqali o&#39;yin sahnasiga yorug&#39;lik va soyalar bera oladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan mavzuni takrorlash (2D grafika turlari va Canvas): 10 daqiqa</li><li>Yangi mavzu: Tanlash vositalari (Marquee, Lasso, Wand): 20 daqiqa</li><li>Chizish vositalari: Brush, Pen, Shape va Gradient: 25 daqiqa</li><li>Qatlamlar, Maskalar va Blending Modes amaliyoti: 15 daqiqa</li><li>Nazorat savollari va dars xulosasi: 10 daqiqa</li></ul></li></ul><hr>",2))]),i("div",g,[i("h2",q,[r(o,{name:"file-text"}),a[3]||(a[3]=l(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=n('<h3 id="_1-tanlash-vositalari-selection-tools" tabindex="-1">1. Tanlash vositalari (Selection Tools) <a class="header-anchor" href="#_1-tanlash-vositalari-selection-tools" aria-label="Permalink to &quot;1. Tanlash vositalari (Selection Tools)&quot;">​</a></h3><p>O&#39;yin obyektlarini kesib olish, fondan ajratish yoki ma&#39;lum bir sohani bo&#39;yash uchun tanlash vositalari ishlatiladi:</p><ol><li><strong>Marquee Tool (M):</strong> To&#39;rtburchak (<code>Rectangular</code>) va aylanma (<code>Elliptical</code>) aniq geometrik sohalarni tanlash. <ul><li><em>Shift</em> bosib turilsa — mukammal kvadrat yoki doira hosil bo&#39;ladi.</li></ul></li><li><strong>Lasso Tool (L):</strong><ul><li><em>Lasso (Erkin):</em> Qo&#39;lda erkin chizib tanlash.</li><li><em>Polygonal Lasso:</em> To&#39;g&#39;ri chiziqli qirralar (burchakli toshlar, binolar) uchun.</li><li><em>Magnetic Lasso:</em> Ranglar kontrasti bo&#39;ylab obyekt chetiga magnitdek o&#39;zi yopishib boruvchi aqlli vosita.</li></ul></li><li><strong>Magic Wand va Quick Selection Tool (W):</strong><ul><li><em>Magic Wand:</em> Bir xil rangdagi barcha piksellarni bitta bosishda tanlaydi (Tolerance parametri orqali sezgirligi sozlanadi). Bir rangli fonni 1 soniyada yo&#39;qotish uchun eng qulay.</li><li><em>Quick Selection:</em> Cho&#39;tka kabi yurgizilganda obyekt shaklini avtomatik aniqlaydi.</li></ul></li></ol><h3 id="_2-chizish-va-shakl-vositalari" tabindex="-1">2. Chizish va shakl vositalari <a class="header-anchor" href="#_2-chizish-va-shakl-vositalari" aria-label="Permalink to &quot;2. Chizish va shakl vositalari&quot;">​</a></h3><ul><li><strong>Brush Tool (B):</strong> Asosiy rasm chizish vositasi. <ul><li><em>Size (O&#39;lcham):</em> <code>[</code> va <code>]</code> tugmalari orqali tezkor o&#39;zgartiriladi.</li><li><em>Hardness (Qattiqlik):</em> 0% (mayin tumanli) dan 100% gacha (o&#39;tkir qirrali).</li><li><em>Opacity va Flow:</em> Shaffoflik darajasi.</li></ul></li><li><strong>Pen Tool (P):</strong> Bezye egri chiziqlari (Bezier curves) orqali o&#39;ta aniq vektor konturlar chizish vositasi. O&#39;yin logotiplari va silliq piktogrammalar uchun eng professional asbob.</li><li><strong>Shape Tool (U):</strong> To&#39;rtburchak, aylana, yulduzcha va maxsus vektor shakllar (o&#39;yin tugmalari va ramkalar uchun).</li><li><strong>Gradient Tool (G):</strong> Ranglarning biridan ikkinchisiga mayin o&#39;tishi (Linear, Radial). O&#39;yin osmoni yoki sehrli qalqon effektlari uchun zarur.</li></ul><h3 id="_3-qatlamlar-layers-va-maskalar-layer-masks" tabindex="-1">3. Qatlamlar (Layers) va Maskalar (Layer Masks) <a class="header-anchor" href="#_3-qatlamlar-layers-va-maskalar-layer-masks" aria-label="Permalink to &quot;3. Qatlamlar (Layers) va Maskalar (Layer Masks)&quot;">​</a></h3><ul><li><strong>Qatlam qoidasi:</strong> Har bir yangi element (qahramon tanasi, quroli, soyasi) yangi qatlamda bo&#39;lishi shart (<code>Ctrl + Shift + N</code>).</li><li><strong>Nega Eraser (o&#39;chirg&#39;ich) o&#39;rniga Maskadan foydalanish kerak?</strong><ul><li>O&#39;chirg&#39;ich bilan o&#39;chirsangiz, piksellar butunlay yo&#39;qoladi (Destruktiv tahrir).</li><li><strong>Layer Mask (Qatlam niqobi):</strong> Qatlamga oq-qora niqob ulaydi. <ul><li><em>Qora cho&#39;tka bilan bo&#39;yalsa:</em> Obyekt ko&#39;rinmay qoladi (yashirinadi);</li><li><em>Oq cho&#39;tka bilan bo&#39;yalsa:</em> Yashiringan obyekt qayta paydo bo&#39;ladi!</li><li>Hech qanday ma&#39;lumot yo&#39;qolmaydi (Non-destructive editing).</li></ul></li></ul></li></ul><h3 id="_4-aralashtirish-rejimlari-blending-modes" tabindex="-1">4. Aralashtirish rejimlari (Blending Modes) <a class="header-anchor" href="#_4-aralashtirish-rejimlari-blending-modes" aria-label="Permalink to &quot;4. Aralashtirish rejimlari (Blending Modes)&quot;">​</a></h3><p>Qatlamlarning bir-biriga ta&#39;sir qilish usuli:</p><ul><li><strong>Multiply:</strong> Tasvirni qoraytiradi (soya va kir effektlari uchun);</li><li><strong>Screen:</strong> Tasvirni yoritadi (olov, lazer, sehrli nur va chaqmoqlar uchun);</li><li><strong>Overlay:</strong> Kontrastni kuchaytiradi (tekstura va rang to&#39;yinganligi uchun).</li></ul><hr>',11))]),i("div",k,[i("h2",y,[r(o,{name:"file-text"}),a[6]||(a[6]=l(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=n('<h3 id="_1-topshiriq-oq-fondan-o-yin-qahramonini-ajratish-oson" tabindex="-1">1-topshiriq. Oq fondan o&#39;yin qahramonini ajratish (oson) <a class="header-anchor" href="#_1-topshiriq-oq-fondan-o-yin-qahramonini-ajratish-oson" aria-label="Permalink to &quot;1-topshiriq. Oq fondan o&#39;yin qahramonini ajratish (oson)&quot;">​</a></h3><p>Oq fonda turgan 2D robot rasmi berilgan. Magic Wand (W) yoki Quick Selection vositasi yordamida robotni oq fondan qanday qilib 3 ta qadamda ajratib olib, yangi shaffof qatlamga o&#39;tkazish mumkin?</p><p><strong>Yechim:</strong></p><ol><li><code>Magic Wand Tool (W)</code> tanlanadi va oq fonga bosiladi (barcha oq piksellar tanlanadi).</li><li>Klaviaturada <code>Ctrl + Shift + I</code> (Invert Selection) bosiladi — endi fon emas, robotning o&#39;zi tanlangan bo&#39;ladi.</li><li><code>Ctrl + J</code> bosiladi — robot avtomatik ravishda alohida shaffof qatlamga ko&#39;chiriladi.</li></ol><h3 id="_2-topshiriq-layer-mask-bilan-olov-effektini-yaratish-o-rta" tabindex="-1">2-topshiriq. Layer Mask bilan olov effektini yaratish (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-layer-mask-bilan-olov-effektini-yaratish-o-rta" aria-label="Permalink to &quot;2-topshiriq. Layer Mask bilan olov effektini yaratish (o&#39;rta)&quot;">​</a></h3><p>O&#39;yin qahramoni qo&#39;liga sehrli qilich tutqazilgan. Qilich tig&#39;idan asta-sekin alangalanuvchi olov chiqishi kerak. O&#39;chirg&#39;ich ishlatmasdan, qanday qilib Layer Mask va Gradient yordamida olovning qilich tutqichiga tutashgan joyini mayin shaffof holatga keltirish mumkin?</p><p><strong>Yechim:</strong></p><ol><li>Olov rasmi qilich qatlamining ustiga joylashtiriladi.</li><li>Olov qatlamiga <code>Add Layer Mask</code> tugmasi bosilib, niqob ulanadi.</li><li><code>Gradient Tool (G)</code> tanlanadi: rang rejimi qora-oq qilinadi.</li><li>Niqob ustida tutqichdan tig&#39; tomon chiziq tortiladi: qora qismi olov boshini mayin yo&#39;qotadi, oq qismi esa tig&#39;dagi olovni to&#39;liq qoldiradi.</li></ol><h3 id="_3-topshiriq-blending-modes-bilan-o-yinda-tungi-chiroq-yaratish-qiyin" tabindex="-1">3-topshiriq. Blending Modes bilan o&#39;yinda tungi chiroq yaratish (qiyin) <a class="header-anchor" href="#_3-topshiriq-blending-modes-bilan-o-yinda-tungi-chiroq-yaratish-qiyin" aria-label="Permalink to &quot;3-topshiriq. Blending Modes bilan o&#39;yinda tungi chiroq yaratish (qiyin)&quot;">​</a></h3><p>Kunduzgi o&#39;rmon sahnasi berilgan. Uni tunda qahramonning qo&#39;lidagi mash&#39;ala (fonar) yorug&#39;ligida ko&#39;rinadigan qilib o&#39;zgartirmoqchisiz. Qatlamlar va Blending Modes yordamida ushbu yorug&#39;lik effektini qanday bajarasiz?</p><p><strong>Yechim:</strong></p><ol><li>Sahnaning ustiga to&#39;q ko&#39;k rang bilan to&#39;ldirilgan yangi qatlam ochiladi va uning rejimi <code>Multiply</code> (yoki Opacity 70%) qilinadi — butun sahna tunga aylanadi.</li><li>Uning ustidan yana bitta bo&#39;sh qatlam ochilib, rejimi <code>Screen</code> yoki <code>Color Dodge</code> ga o&#39;tkaziladi.</li><li>Yumshoq (Hardness 0%) sariq-olovrang <code>Brush (B)</code> olinadi va qahramon mash&#39;alasi joylashgan nuqtaga bitta katta bosiladi.</li><li><em>Natija:</em> <code>Screen</code> rejimi tungi qora qatlamni yorib o&#39;tib, daraxtlar va yo&#39;l ustiga realistik tilla rang nur taratadi.</li></ol><hr>',13))]),i("div",c,[i("h2",b,[r(o,{name:"file-text"}),a[9]||(a[9]=l(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=n("<ol><li>Photoshopda obyektni tanlashni teskarisiga o&#39;girish (Invert Selection) tezkor tugmasi qaysi? <ul><li><em>Javob:</em> <code>Ctrl + Shift + I</code> (Mac&#39;da <code>Cmd + Shift + I</code>).</li></ul></li><li>Nima uchun professional dizaynerlar o&#39;chirg&#39;ich (Eraser) o&#39;rniga Layer Mask ishlatishadi? <ul><li><em>Javob:</em> Chunki Layer Mask piksellarni yo&#39;qotmaydi, xato bo&#39;lsa oq cho&#39;tka bilan istalgan vaqtda qayta tiklash mumkin (Non-destructive).</li></ul></li><li>Qaysi Blending Mode yorug&#39;lik va chaqnash effektlari uchun eng yaxshi natija beradi? <ul><li><em>Javob:</em> Screen (yoki Color Dodge / Linear Dodge).</li></ul></li><li>Mo&#39;yqalam (Brush) o&#39;lchamini klaviaturada qaysi tugmalar bilan tezkor o&#39;zgartirish mumkin? <ul><li><em>Javob:</em> <code>[</code> (kichraytirish) va <code>]</code> (kattalashtirish).</li></ul></li></ol><hr>",2))]),i("div",v,[i("h2",f,[r(o,{name:"house"}),a[12]||(a[12]=l(" Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=i("p",null,"Kompyuterda (yoki daftarda sxematik tarzda):",-1)),a[15]||(a[15]=i("ol",null,[i("li",null,[l("O'yin bosh qahramoni uchun 3 ta qatlamdan iborat loyiha tuzing: "),i("ul",null,[i("li",null,"1-qatlam: Qahramon soyasi (Yerda);"),i("li",null,"2-qatlam: Qahramon tanasi va libosi;"),i("li",null,"3-qatlam: Qahramon qo'lidagi qurol yoki qalqon.")])]),i("li",null,"Layer Mask qanday ishlashini o'z so'zlaringiz bilan 3 ta jumlada tushuntiring.")],-1))])])}const j=t(d,[["render",p]]);export{x as __pageData,j as default};
